use tauri_build::{AppManifest, Attributes};

// Release builds register only `COMMANDS`; debug builds add the dev-only ones. tauri-build writes one
// `permissions/autogenerated/<cmd>.toml` per command and never deletes stale ones, so a release build
// first removes the dev-only files a previous debug build left behind.

/// Release manifest: the dev command must never appear here.
const COMMANDS: &[&str] = &[
    "get_status",
    "get_settings",
    "save_settings",
    "list_midi_sources",
    "list_audio_inputs",
    "ui_command",
];
const DEV_COMMANDS: &[&str] = &[
    "get_status",
    "get_settings",
    "save_settings",
    "list_midi_sources",
    "list_audio_inputs",
    "ui_command",
    "dev_paint_test",
    "dev_mic_level",
];

fn main() {
    let commands = if std::env::var("PROFILE").as_deref() == Ok("debug") {
        DEV_COMMANDS
    } else {
        remove_dev_permissions();
        COMMANDS
    };
    if let Err(e) = tauri_build::try_build(
        Attributes::new().app_manifest(AppManifest::new().commands(commands)),
    ) {
        eprintln!("tauri build failed: {e:#}");
        std::process::exit(1);
    }
}

fn remove_dev_permissions() {
    let dir = std::path::Path::new("permissions/autogenerated");
    for cmd in DEV_COMMANDS.iter().filter(|c| !COMMANDS.contains(c)) {
        let file = dir.join(format!("{cmd}.toml"));
        match std::fs::remove_file(&file) {
            Ok(()) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => {
                eprintln!("cannot remove stale dev permission {}: {e}", file.display());
                std::process::exit(1);
            }
        }
    }
}
